import{_ as a,a as o,b as t,c as r}from"./chunks/kuka_theme_4.7PEyRC9o.js";import{_ as i,a as n,b as l,c as s,d as c,e as d,f as u,g as p,h as m,i as h,j as g}from"./chunks/sort_declarations.DU86DpOi.js";import{_ as f}from"./chunks/inlay_hints.BQUZLqE3.js";import{_ as k}from"./chunks/kuka_commands.D8cXdGAR.js";import{_ as b}from"./chunks/kuka_control_center.CLR_jZ0I.js";import{_}from"./chunks/krc_backup_diff.FXLcgDew.js";import{_ as P}from"./chunks/control_flow_graph.hbF2msHR.js";import{_ as S}from"./chunks/cell_flowchart.DffnEFAW.js";import{_ as y,o as A,c as C,a0 as x}from"./chunks/framework.QP0FkqbW.js";const G=JSON.parse('{"title":"KUKA KRL Professional — Features Wiki & Complete Encyclopedia (v1.8.5 Pro Hub)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md"}'),v={name:"guide/features.md"};function K(D,e,I,q,T,L){return A(),C("div",null,[...e[0]||(e[0]=[x('<h1 id="kuka-krl-professional-—-features-wiki-complete-encyclopedia-v1-8-5-pro-hub" tabindex="-1">KUKA KRL Professional — Features Wiki &amp; Complete Encyclopedia (v1.8.5 Pro Hub) <a class="header-anchor" href="#kuka-krl-professional-—-features-wiki-complete-encyclopedia-v1-8-5-pro-hub" aria-label="Permalink to &quot;KUKA KRL Professional — Features Wiki &amp; Complete Encyclopedia (v1.8.5 Pro Hub)&quot;">​</a></h1><p>Welcome to the official feature wiki for <strong>KUKA KRL Professional Extension</strong> for VS Code.</p><p>Our extension is an industrial-grade development environment and static code analyzer built by robotics automation engineers specifically for programming KUKA industrial robots (KSS 8.3 / 8.5 / 8.6 / 8.7).</p><p>Below is an exhaustive breakdown of all <strong>26 key features</strong> (15 Community free core features and 11 Pro industrial tools), their real-world commissioning benefits, keyboard shortcuts, and media demonstrations.</p><hr><h2 id="🟢-part-1-community-core-features-free-features" tabindex="-1">🟢 Part 1. Community &amp; Core Features (Free Features) <a class="header-anchor" href="#🟢-part-1-community-core-features-free-features" aria-label="Permalink to &quot;🟢 Part 1. Community &amp; Core Features (Free Features)&quot;">​</a></h2><p>Available completely free to accelerate daily KRL programming and field engineering.</p><hr><h3 id="_1-krl-syntax-highlighting" tabindex="-1">1. KRL Syntax Highlighting <a class="header-anchor" href="#_1-krl-syntax-highlighting" aria-label="Permalink to &quot;1. KRL Syntax Highlighting&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Standard text editors treat <code>.src</code>, <code>.dat</code>, and <code>.sub</code> files as plain text. This extension performs full context-aware parsing of KRL syntax, accurately highlighting data types (<code>INT</code>, <code>REAL</code>, <code>BOOL</code>, <code>E6POS</code>), system variables (<code>$POS_ACT</code>, <code>$VEL.CP</code>), operators, and KUKA WorkVisual <code>FOLD</code> blocks.</li><li><strong>Field Benefit:</strong> Typos and unclosed strings are caught visually before code reaches the robot controller.</li><li><strong>Before &amp; After Installation:</strong></li></ul><h4 id="before-installation-plain-text" tabindex="-1">Before Installation (Plain Text): <a class="header-anchor" href="#before-installation-plain-text" aria-label="Permalink to &quot;Before Installation (Plain Text):&quot;">​</a></h4><p><img src="'+a+'" alt="Syntax Highlighting Before"></p><h4 id="after-installation-high-contrast-krl-syntax" tabindex="-1">After Installation (High-Contrast KRL Syntax): <a class="header-anchor" href="#after-installation-high-contrast-krl-syntax" aria-label="Permalink to &quot;After Installation (High-Contrast KRL Syntax):&quot;">​</a></h4><p><img src="'+i+'" alt="Syntax Highlighting After"></p><hr><h3 id="_2-exclusive-kuka-themes-6-tailored-color-themes" tabindex="-1">2. Exclusive KUKA Themes (6 Tailored Color Themes) <a class="header-anchor" href="#_2-exclusive-kuka-themes-6-tailored-color-themes" aria-label="Permalink to &quot;2. Exclusive KUKA Themes (6 Tailored Color Themes)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> A curated suite of 6 high-contrast themes designed for industrial laptops under factory floor lighting and SmartPAD screens: <ol><li><strong>Industrial Dark</strong> (Signature KUKA style with industrial orange <code>#FF6600</code>)</li><li><strong>WorkVisual Dark</strong> (Matches WorkVisual IDE dark mode)</li><li><strong>WorkVisual Light</strong> (Bright mode for outdoor / outdoor integration)</li><li><strong>Midnight OLED</strong> (Pure black background for laptop battery saving)</li><li><strong>Blueprint</strong> (Engineering CAD style)</li><li><strong>Industrial Light</strong> (High contrast light theme)</li></ol></li><li><strong>Shortcut:</strong> Press <code>Ctrl + K</code>, then <code>Ctrl + T</code> to switch between KUKA themes.</li><li><strong>Screenshots:</strong></li></ul><p><img src="'+n+'" alt="KUKA Industrial Theme 1"></p><p><img src="'+o+'" alt="KUKA Industrial Theme 2"></p><p><img src="'+t+'" alt="KUKA Industrial Theme 3"></p><p><img src="'+r+'" alt="KUKA Industrial Theme 4"></p><hr><h3 id="_3-smart-autocomplete-kss-8-7-system-variables" tabindex="-1">3. Smart Autocomplete (KSS 8.7 &amp; System Variables) <a class="header-anchor" href="#_3-smart-autocomplete-kss-8-7-system-variables" aria-label="Permalink to &quot;3. Smart Autocomplete (KSS 8.7 &amp; System Variables)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Typing <code>$</code> or variable characters instantly triggers an intelligent dropdown covering 350+ KSS 8.7 system variables (<code>$POS_ACT</code>, <code>$VEL_ACT</code>, <code>$BASE</code>, <code>$TOOL</code>, <code>$IN</code>, <code>$OUT</code>, <code>$MODE_OP</code>), data types, and user subroutines.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+l+'" alt="Smart Autocomplete Demo"></p><hr><h3 id="_4-trilingual-nls-localization-en-ru-tr" tabindex="-1">4. Trilingual NLS Localization (EN / RU / TR) <a class="header-anchor" href="#_4-trilingual-nls-localization-en-ru-tr" aria-label="Permalink to &quot;4. Trilingual NLS Localization (EN / RU / TR)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Full native internationalization of hover info, diagnostics, context menus, TreeViews, and the Control Center into <strong>English</strong>, <strong>Russian</strong>, and <strong>Turkish (Türkçe)</strong>.</li><li><strong>Field Benefit:</strong> Seamless multi-national engineering teamwork across European and Turkish automotive plants.</li></ul><hr><h3 id="_5-hardware-signal-inlay-hints-in-out-anin-anout" tabindex="-1">5. Hardware Signal Inlay Hints ($IN / $OUT / $ANIN / $ANOUT) <a class="header-anchor" href="#_5-hardware-signal-inlay-hints-in-out-anin-anout" aria-label="Permalink to &quot;5. Hardware Signal Inlay Hints ($IN / $OUT / $ANIN / $ANOUT)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Hardware I/O signals in KRL use channel numbers like <code>$IN[1]</code> or <code>$OUT[4]</code>. Real-time <strong>Inlay Hints</strong> inject virtual text inline (e.g., <code>$IN[1]</code> <code>: diPartReady</code>), pulling comments directly from <code>.dat</code> files without altering source code.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+f+'" alt="Inlay Hints Demo"></p><hr><h3 id="_6-hover-documentation-read-write-status" tabindex="-1">6. Hover Documentation &amp; Read/Write Status <a class="header-anchor" href="#_6-hover-documentation-read-write-status" aria-label="Permalink to &quot;6. Hover Documentation &amp; Read/Write Status&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Hovering over any system variable (like <code>$VEL.CP</code>, <code>$POS_ACT</code>) displays an official KSS manual popup with data types, value limits, and access permissions (<strong>Read-Only / Read-Write</strong>).</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+s+'" alt="Hover Info Demo"></p><hr><h3 id="_7-cross-file-navigation-src-↔-dat-go-to-definition" tabindex="-1">7. Cross-File Navigation (.src ↔ .dat Go-to-Definition) <a class="header-anchor" href="#_7-cross-file-navigation-src-↔-dat-go-to-definition" aria-label="Permalink to &quot;7. Cross-File Navigation (.src ↔ .dat Go-to-Definition)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> In KRL, logic resides in <code>.src</code> while point declarations (<code>E6POS</code>, <code>$TOOL</code>, <code>$BASE</code>) sit inside <code>.dat</code>. Pressing <code>F12</code> or <code>Ctrl + Click</code> jumps directly from point references in <code>.src</code> to their exact declaration inside <code>.dat</code>.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+c+'" alt="Go-to-Definition Demo"></p><hr><h3 id="_8-find-all-references-shift-alt-f12" tabindex="-1">8. Find All References (<code>Shift+Alt+F12</code>) <a class="header-anchor" href="#_8-find-all-references-shift-alt-f12" aria-label="Permalink to &quot;8. Find All References (`Shift+Alt+F12`)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Pressing <code>Shift + Alt + F12</code> on any variable or subroutine opens a side panel listing every single usage across all files in your workspace.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+d+'" alt="Find All References Demo"></p><hr><h3 id="_9-global-krl-formatter-code-alignment-indentation" tabindex="-1">9. Global KRL Formatter (Code Alignment &amp; Indentation) <a class="header-anchor" href="#_9-global-krl-formatter-code-alignment-indentation" aria-label="Permalink to &quot;9. Global KRL Formatter (Code Alignment &amp; Indentation)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Pressing <code>Shift + Alt + F</code> automatically formats messy code: aligns <code>=</code> signs in matrix assignments, standardizes <code>IF/FOR/WHILE</code> nesting, and cleans up <code>;FOLD / ;ENDFOLD</code> blocks.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+u+'" alt="Code Formatter Demo"></p><hr><h3 id="_10-quick-fold-toolbar-buttons" tabindex="-1">10. Quick Fold Toolbar Buttons <a class="header-anchor" href="#_10-quick-fold-toolbar-buttons" aria-label="Permalink to &quot;10. Quick Fold Toolbar Buttons&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Top editor toolbar icons 🙈 (<code>krl.foldAll</code>) and 📖 (<code>krl.unfoldAll</code>) allow 1-click collapse or expansion of all Inline Form <code>FOLD</code> structures.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+p+'" alt="Quick Fold Toolbar Demo"></p><hr><h3 id="_11-kuka-commands-treeview-panel" tabindex="-1">11. KUKA COMMANDS TreeView Panel <a class="header-anchor" href="#_11-kuka-commands-treeview-panel" aria-label="Permalink to &quot;11. KUKA COMMANDS TreeView Panel&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> A dedicated Activity Bar sidebar panel categorizing all extension tools into 4 intuitive categories (Engineering Tools, Network &amp; Safety, KRL Editing, Reports).</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+k+'" alt="KUKA COMMANDS Demo"></p><hr><h3 id="_12-krl-i-o-signals-panel" tabindex="-1">12. KRL I/O Signals Panel <a class="header-anchor" href="#_12-krl-i-o-signals-panel" aria-label="Permalink to &quot;12. KRL I/O Signals Panel&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Side panel listing all project <code>$IN</code>, <code>$OUT</code>, and <code>SIGNAL</code> declarations with search and comment inspection.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+m+'" alt="KRL I/O Signals Demo"></p><hr><h3 id="_13-unused-variable-cleaner" tabindex="-1">13. Unused Variable Cleaner <a class="header-anchor" href="#_13-unused-variable-cleaner" aria-label="Permalink to &quot;13. Unused Variable Cleaner&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Command <code>KRL: Clean Up Unused Variables</code> scans <code>.dat</code> files for unreferenced <code>DECL</code> statements and cleans them up safely.</li></ul><hr><h3 id="_14-workvisual-git-metadata-cleaner" tabindex="-1">14. WorkVisual Git Metadata Cleaner <a class="header-anchor" href="#_14-workvisual-git-metadata-cleaner" aria-label="Permalink to &quot;14. WorkVisual Git Metadata Cleaner&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Strips IDE metadata noise (<code>&amp;ACCESS RVP</code>, <code>&amp;REL 1</code>, <code>&amp;PARAM</code>) from headers to keep Git diffs focused purely on code logic changes.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+h+'" alt="Git Metadata Cleaner Demo"></p><hr><h3 id="_15-sort-declarations" tabindex="-1">15. Sort Declarations <a class="header-anchor" href="#_15-sort-declarations" aria-label="Permalink to &quot;15. Sort Declarations&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Automatically sorts data type declarations (<code>INT</code>, <code>REAL</code>, <code>BOOL</code>, <code>E6POS</code>) in <code>.dat</code> files alphabetically and by category.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+g+'" alt="Sort Declarations Demo"></p><hr><h2 id="👑-part-2-pro-industrial-edition-features" tabindex="-1">👑 Part 2. Pro &amp; Industrial Edition Features <a class="header-anchor" href="#👑-part-2-pro-industrial-edition-features" aria-label="Permalink to &quot;👑 Part 2. Pro &amp; Industrial Edition Features&quot;">​</a></h2><p>Designed for system integrators, robotics leads, and safety compliance audits.</p><hr><h3 id="_16-kuka-control-center-dashboard-v1-8-5-pro-hub" tabindex="-1">16. KUKA Control Center Dashboard (v1.8.5 Pro Hub) <a class="header-anchor" href="#_16-kuka-control-center-dashboard-v1-8-5-pro-hub" aria-label="Permalink to &quot;16. KUKA Control Center Dashboard (v1.8.5 Pro Hub)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Centralized Fluent UI dashboard (<code>krl.openControlCenter</code>) providing 1-click access to all Pro tools, workspace health metrics, license manager, and Telegram support.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+b+'" alt="KUKA Control Center Demo"></p><hr><h3 id="_17-vs-code-telegram-support-chat-panel" tabindex="-1">17. VS Code Telegram Support Chat Panel <a class="header-anchor" href="#_17-vs-code-telegram-support-chat-panel" aria-label="Permalink to &quot;17. VS Code Telegram Support Chat Panel&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Embedded support chat window (<code>krl.openTelegramChat</code>) linked with <strong><code>@kukakrlbot</code></strong> for sending feedback, logs, and screenshots straight to lead developers.</li></ul><hr><h3 id="_18-autonomous-helpdesk-app-kukaadminhelpdesk-exe" tabindex="-1">18. Autonomous Helpdesk App (<code>KukaAdminHelpdesk.exe</code>) <a class="header-anchor" href="#_18-autonomous-helpdesk-app-kukaadminhelpdesk-exe" aria-label="Permalink to &quot;18. Autonomous Helpdesk App (`KukaAdminHelpdesk.exe`)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Standalone Windows admin console for automation team leads to monitor engineer workspace statuses (🟢 ONLINE / 🟡 IDLE / 🔴 OFFLINE).</li></ul><hr><h3 id="_19-krc-backup-diff-point-delta-inspector" tabindex="-1">19. KRC Backup Diff &amp; Point Delta Inspector <a class="header-anchor" href="#_19-krc-backup-diff-point-delta-inspector" aria-label="Permalink to &quot;19. KRC Backup Diff &amp; Point Delta Inspector&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Loads SmartPAD KRC4/KRC5 <code>.zip</code> backup archives, compares them against local files, and calculates physical coordinate deltas ($\\Delta X, \\Delta Y, \\Delta Z, \\Delta A, \\Delta B, \\Delta C$) for points.</li><li><strong>Field Benefit:</strong> Prevents robot collisions caused by manual point touch-ups on the SmartPAD.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+_+'" alt="KRC Backup Diff Demo"></p><hr><h3 id="_20-interactive-motion-trajectory-snippet-generator" tabindex="-1">20. Interactive Motion Trajectory &amp; Snippet Generator <a class="header-anchor" href="#_20-interactive-motion-trajectory-snippet-generator" aria-label="Permalink to &quot;20. Interactive Motion Trajectory &amp; Snippet Generator&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> 2-column GUI builder for KUKA motions (<code>PTP</code>, <code>LIN</code>, <code>CIRC</code>, <code>SPTP</code>, <code>SLIN</code>, <code>SCIRC</code>, <code>SPLINE</code>). Generates real-time vector SVG scheme diagrams with TCP jerk profiles (<code>$SGEAR_JERK</code>) and blending parameters (<code>C_PTP</code>, <code>C_DIS</code>, <code>C_Spl</code>).</li></ul><hr><h3 id="_21-interactive-flowchart-viewer-control-flow-graph" tabindex="-1">21. Interactive Flowchart Viewer (Control Flow Graph) <a class="header-anchor" href="#_21-interactive-flowchart-viewer-control-flow-graph" aria-label="Permalink to &quot;21. Interactive Flowchart Viewer (Control Flow Graph)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Converts <code>.src</code> program logic into clean Mermaid SVG control flow graphs (<code>krl.showFlowchart</code>). Click subprograms to drill down. SVG export enabled.</li><li><strong>Demonstration:</strong></li></ul><p><img src="'+P+'" alt="Control Flow Graph Demo"></p><h4 id="vector-flowchart-example" tabindex="-1">Vector Flowchart Example: <a class="header-anchor" href="#vector-flowchart-example" aria-label="Permalink to &quot;Vector Flowchart Example:&quot;">​</a></h4><p><img src="'+S+'" alt="Cell Flowchart SVG"></p><hr><h3 id="_22-ethernetkrl-eki-xml-suite-handler-generator" tabindex="-1">22. EthernetKRL (EKI) XML Suite &amp; Handler Generator <a class="header-anchor" href="#_22-ethernetkrl-eki-xml-suite-handler-generator" aria-label="Permalink to &quot;22. EthernetKRL (EKI) XML Suite &amp; Handler Generator&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Validates EthernetKRL XML communication schemas and automatically generates KRL networking modules (<code>EKI_Init</code>, <code>EKI_Open</code>, <code>EKI_Get*</code>, <code>EKI_Send*</code>).</li></ul><hr><h3 id="_23-industrial-safety-velocity-diagnostics" tabindex="-1">23. Industrial Safety &amp; Velocity Diagnostics <a class="header-anchor" href="#_23-industrial-safety-velocity-diagnostics" aria-label="Permalink to &quot;23. Industrial Safety &amp; Velocity Diagnostics&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Automated safety inspector (<code>KRL: Run Safety Check</code>) alerting on: <ol><li>Excessive Cartesian velocity (<code>$VEL.CP &gt; 3.0 m/s</code>).</li><li>Uninitialized <code>$TOOL</code> or <code>$BASE</code> values before motion commands.</li><li>Invisible non-ASCII or Cyrillic characters inside executable lines.</li></ol></li></ul><hr><h3 id="_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" tabindex="-1">24. AI-Supportive Domain Context Tools (<code>@kuka /get-io-matrix</code>, <code>@kuka /check-safety</code>) <a class="header-anchor" href="#_24-ai-supportive-domain-context-tools-kuka-get-io-matrix-kuka-check-safety" aria-label="Permalink to &quot;24. AI-Supportive Domain Context Tools (`@kuka /get-io-matrix`, `@kuka /check-safety`)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Grounding tools for AI assistants (Google Antigravity IDE / Copilot) providing exact KSS 8.7 AST, I/O matrices, and safety audit reports.</li></ul><hr><h3 id="_25-3-point-frame-calculator-base-tool-math" tabindex="-1">25. 3-Point Frame Calculator (BASE &amp; TOOL Math) <a class="header-anchor" href="#_25-3-point-frame-calculator-base-tool-math" aria-label="Permalink to &quot;25. 3-Point Frame Calculator (BASE &amp; TOOL Math)&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> 3D geometric frame transformation tool (<code>krl.showCalculator</code>). Computes <code>BASE_DATA[x]</code> Euler angles (A, B, C) from 3 recorded points (Origin, X-Axis, XY-Plane).</li></ul><hr><h3 id="_26-quality-acceptance-report-generator" tabindex="-1">26. Quality Acceptance Report Generator <a class="header-anchor" href="#_26-quality-acceptance-report-generator" aria-label="Permalink to &quot;26. Quality Acceptance Report Generator&quot;">​</a></h3><ul><li><strong>Purpose &amp; Usage:</strong> Generates comprehensive HTML/JSON project quality reports for client acceptance sign-off.</li></ul><hr><h2 id="🛠️-purchase-support" tabindex="-1">🛠️ Purchase &amp; Support <a class="header-anchor" href="#🛠️-purchase-support" aria-label="Permalink to &quot;🛠️ Purchase &amp; Support&quot;">​</a></h2><ul><li><strong>Get Pro License:</strong> <a href="https://liskin.lemonsqueezy.com" target="_blank" rel="noreferrer">LiskinLabs Store (Lemon Squeezy)</a></li><li><strong>Telegram Support Bot:</strong> <a href="https://t.me/kukakrlbot" target="_blank" rel="noreferrer">@kukakrlbot</a></li></ul>',115)])])}const H=y(v,[["render",K]]);export{G as __pageData,H as default};
